import { record } from '../../../../schema/record/index.js';
import { fromSchemaDTO } from './attribute.js';
/**
 * @debt feature "handle defaults, links & validators"
 */
export const fromRecordSchemaDTO = ({ keyDefault, putDefault, updateDefault, keyLink, putLink, updateLink, keys, elements, ...props }) => {
    keyDefault;
    putDefault;
    updateDefault;
    keyLink;
    putLink;
    updateLink;
    return record(fromSchemaDTO(keys), fromSchemaDTO(elements), props);
};
